<?php header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/conexion.php';try{$rows=$pdo->query('SELECT provincia,distrito,costo,dias_estimados FROM tarifas_envio WHERE activa=1')->fetchAll();$out=[];foreach($rows as $r)$out[$r['provincia'].'|'.$r['distrito']]=['costo'=>(float)$r['costo'],'dias'=>$r['dias_estimados']];echo json_encode(['success'=>true,'tarifas'=>$out],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){echo json_encode(['success'=>true,'tarifas'=>new stdClass()]);}
